import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"HTTP 402 and the x402 Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"learn/02-agent-payments/http-402-and-x402.md","filePath":"learn/02-agent-payments/http-402-and-x402.md","lastUpdated":1792595354000}'),r={name:"learn/02-agent-payments/http-402-and-x402.md"};function o(i,e,p,d,l,c){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="http-402-and-the-x402-protocol" tabindex="-1">HTTP 402 and the x402 Protocol <a class="header-anchor" href="#http-402-and-the-x402-protocol" aria-label="Permalink to &quot;HTTP 402 and the x402 Protocol&quot;">​</a></h1><h2 id="what-does-http-402-mean" tabindex="-1">What does HTTP 402 mean? <a class="header-anchor" href="#what-does-http-402-mean" aria-label="Permalink to &quot;What does HTTP 402 mean?&quot;">​</a></h2><p>HTTP status <code>402 Payment Required</code> is reserved for payment-related use. For years it had no broadly adopted standard payment flow. A service can use it to tell a client that a requested resource requires payment, but the status code alone does not define how to pay or prove that payment occurred.</p><h2 id="the-basic-x402-pattern" tabindex="-1">The basic x402 pattern <a class="header-anchor" href="#the-basic-x402-pattern" aria-label="Permalink to &quot;The basic x402 pattern&quot;">​</a></h2><p>x402 uses HTTP request and response conventions to communicate payment requirements and payment evidence. A simplified flow is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client requests a resource</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Server returns 402 with payment requirements</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Client evaluates the terms and creates payment data</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Client retries with payment information</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Server or facilitator verifies/processes it</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Server returns the resource</span></span></code></pre></div><p>The exact fields and lifecycle depend on the protocol version and implementation. A 402 response is a request for payment, not proof that the terms are safe or authorized.</p><h2 id="what-x402-provides—and-what-it-does-not" tabindex="-1">What x402 provides—and what it does not <a class="header-anchor" href="#what-x402-provides—and-what-it-does-not" aria-label="Permalink to &quot;What x402 provides—and what it does not&quot;">​</a></h2><p>x402 standardizes a way for web services and clients to negotiate machine-readable payment requirements and continue a request with payment information. It can make pay-per-request services easier to integrate without a conventional account or subscription.</p><p>It does not decide whether an agent should pay, how much it may spend, which providers are trusted, or how an application should recover from uncertain outcomes. The buyer still needs to validate network, asset, amount, and recipient and apply independent spending policy. Payment verification and resource fulfillment must also be tracked carefully.</p><h2 id="how-agentpay-relates" tabindex="-1">How AgentPay relates <a class="header-anchor" href="#how-agentpay-relates" aria-label="Permalink to &quot;How AgentPay relates&quot;">​</a></h2><p>The roles are complementary: x402 describes a payment interaction; AgentPay provides controls around whether an agent is allowed to proceed and how budgets, identity, retries, and audit are handled. A protocol can carry a payment request without being the financial authority for the agent.</p>`,12)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
